#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
build/baha_triage.py —— 把 private/baha/digest-browser.json（69 個分類、554 篇巴哈老攻略文章）
合併成 private/baha/triage.json，供判斷哪些文章可以整合進現行攻略站使用。

分類方式：
- keep   機制/觀念類，不隨版本變，站上沒有
- verify 有價值但含具體數值，需要跟現行資料表對照才敢採用
- dup    站上已經有更好更新的版本
- drop   過期或與攻略無關（板規、公告、小說創作、圖片創作等）

CLASSIFICATIONS 是逐篇人工（LLM 輔助）讀過全文後的判斷結果，用文章 url 當 key，
對應到 class / why / topics / extract / conflicts 五個欄位。

本腳本本身**不會重新做分類判斷**，只負責：
  1. 讀取 digest-browser.json，取得每篇文章的 category / title / author / date / url
  2. 用 url 對到 CLASSIFICATIONS 裡的判斷結果
  3. 驗證：554 篇一篇不漏、class 只能是四選一、keep/verify 的 extract 不可為空
  4. 輸出 counts + articles 到 private/baha/triage.json

若要修改某篇文章的分類，直接編輯下面 CLASSIFICATIONS 字典裡對應 url 的內容即可，
改完重跑 `python3 build/baha_triage.py` 就會重新產生 triage.json。
"""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "private" / "baha" / "digest-browser.json"
OUT = ROOT / "private" / "baha" / "triage.json"

VALID_CLASSES = ("keep", "verify", "dup", "drop")

