def main():
    with open(SRC, encoding="utf-8") as f:
        src = json.load(f)

    articles = []
    seen_urls = set()

    for cat in src["categories"]:
        cat_name = cat["name"]
        for art in cat["articles"]:
            url = art["url"]
            c = CLASSIFICATIONS.get(url)
            if c is None:
                print(f"FATAL: 找不到分類 url={url} title={art.get('title')!r}", file=sys.stderr)
                sys.exit(1)
            if c["class"] not in VALID_CLASSES:
                print(f"FATAL: class 不合法 url={url} class={c['class']!r}", file=sys.stderr)
                sys.exit(1)
            if c["class"] in ("keep", "verify") and not c.get("extract", "").strip():
                print(f"FATAL: {c['class']} 缺少 extract url={url}", file=sys.stderr)
                sys.exit(1)

            articles.append({
                "category": cat_name,
                "title": art.get("title", ""),
                "author": art.get("author", ""),
                "date": art.get("date", ""),
                "url": url,
                "class": c["class"],
                "why": c.get("why", ""),
                "topics": c.get("topics", []),
                "extract": c.get("extract", ""),
                "conflicts": c.get("conflicts", ""),
            })
            seen_urls.add(url)

    expected_total = 554
    if len(articles) != expected_total:
        print(f"FATAL: 篇數不對，預期 {expected_total} 篇，實際 {len(articles)} 篇", file=sys.stderr)
        sys.exit(1)

    unused = set(CLASSIFICATIONS) - seen_urls
    if unused:
        print(f"WARNING: CLASSIFICATIONS 裡有 {len(unused)} 筆 url 在來源資料中找不到對應文章（可能來源已變動）", file=sys.stderr)

    counts = {"keep": 0, "verify": 0, "dup": 0, "drop": 0}
    for a in articles:
        counts[a["class"]] += 1

    result = {"counts": counts, "articles": articles}

    OUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
        f.write("\n")

    print(f"寫入 {OUT}")
    print(f"counts = {counts}")


if __name__ == "__main__":
    main()
